4	import { AnimatePresence, motion } from "motion/react";
5	import { parseAsStringLiteral, useQueryState } from "nuqs";
6	import { useEffect } from "react";
7	import { Era1Playground } from "./demos/era1-playground";
8	import { Era2Companion } from "./demos/era2-companion";
9	import { Era2Extraction } from "./demos/era2-companion/extraction-demo";
10	import { Era3Harness } from "./demos/era3-harness";
11	import { Era3Ladder } from "./demos/era3-ladder";
12	import { Era3Loop } from "./demos/era3-loop";
13	import { Era3Meter } from "./demos/era3-meter";
14	import { Era3Pipeline } from "./demos/era3-pipeline";
15	import { Era4Runtime } from "./demos/era4-runtime";
16	import { EraPanel } from "./era-panel";
17	import { FieldNote } from "./field-note";
18	import { Intro } from "./intro";
19	import { StepperHeader } from "./stepper-header";
20	import { isArrowConsumingTarget, stepKeyDirection } from "./step-keys";
21	import { getAdjacentStep, STEPS, type StepId } from "./steps";
22	import { Synthesis } from "./synthesis";
23	
24	const STEP_IDS = STEPS.map((s) => s.id);
25	
26	export function Masterclass() {
27	  const [step, setStep] = useQueryState(
28	    "step",
29	    parseAsStringLiteral(STEP_IDS as StepId[])
30	      .withDefault("intro")
31	      .withOptions({ history: "push" })
32	  );
33	
34	  const prev = getAdjacentStep(step, "prev");
35	  const next = getAdjacentStep(step, "next");
36	
37	  useEffect(() => {
38	    const onKeyDown = (event: KeyboardEvent) => {
39	      const dir = stepKeyDirection(event);
40	      if (!dir || isArrowConsumingTarget(event.target)) {
41	        return;
42	      }
43	      const adjacent = getAdjacentStep(step, dir);
44	      if (adjacent) {
45	        setStep(adjacent);
46	      }
47	    };
48	    window.addEventListener("keydown", onKeyDown);
49	    return () => window.removeEventListener("keydown", onKeyDown);
50	  }, [step, setStep]);
51	
52	  return (
53	    <div className="flex min-h-dvh flex-col">
54	      <StepperHeader current={step} onSelect={setStep} />
55	      <main className="mx-auto w-full max-w-5xl flex-1 px-4 py-12 sm:py-16">
56	        <AnimatePresence mode="wait">
57	          <motion.div
58	            animate={{ opacity: 1 }}
59	            exit={{ opacity: 0 }}
60	            initial={{ opacity: 0 }}
61	            key={step}
62	            transition={{ duration: 0.2 }}
63	          >
64	            {step === "intro" && (
65	              <Intro onBegin={() => setStep("completion")} />
66	            )}
67	            {step === "completion" && (
68	              <EraPanel
69	                deepCut={
70	                  <p>
71	                    There was no intent model here — only continuation.
72	                    OpenAI&apos;s fix was post-training: humans wrote answers,
73	                    the model was tuned on them, then ranked by preference
74	                    (InstructGPT, 2022). The canonical failure in the literature
75	                    is this very demo — asked for the capital of France, a base
76	                    model offers the capital of Germany, as a question.
77	                    Post-trained answers were preferred roughly 85% of the time
78	                    over the base model&apos;s; ChatGPT shipped on that flip
79	                    nine months later.
80	                  </p>
81	                }
82	                expandLabel="Did you know? It was never listening."
83	                name="The completion machine"
84	                reality="Nobody was shipping software with this. But everything that came after is still this machine underneath: you feed it the start of a pattern and it continues — unaware of what you meant. Getting knowledge out took craft, until OpenAI taught it a format."
85	                years="2019–2022"
86	              >
87	                <Era1Playground />
88	                <FieldNote date="2019–2021">
89	                  No notes survive from these years — I have none. I was
90	                  teaching juniors to write these functions by hand while a
91	                  model autocompleted them badly. We hadn&apos;t met yet.
92	                </FieldNote>
93	              </EraPanel>
94	            )}
95	            {step === "integration" && (
96	              <EraPanel
97	                deepCut={
98	                  <p>
99	                    The speed was real, and so was the ceiling: the model saw
100	                    one file, one selection. Cursor had to fork VS Code to raise
101	                    it — the extension API allows a sidebar, not an editor that
102	                    thinks; indexing a codebase and editing across files needs
103	                    the core. That&apos;s why Copilot rode along as a plugin
104	                    while Cursor rebuilt the vehicle. The ceiling finally
105	                    cracked late in 2024, when models learned to reason —
106	                    multi-step thinking, the ingredient agents were waiting for.
107	                  </p>
108	                }
109	                expandLabel="Did you know? You were the bus."
110	                name="Extraction → Integration"
111	                reality="It answers now — in a browser tab, a world away from your code. You ferry context in and answers out by hand, until the chat moves into the editor and your selection becomes its context. Either way the verdict held: a senior engineer was faster. The model missed the file next door and the framework's basics, and correcting it cost more than writing it."
112	                years="2022–2024"
113	              >
114	                <Era2Extraction />
115	                <p className="mb-4 max-w-2xl text-muted-foreground text-sm">
116	                  Then the chat moved into the editor, and your selection became
117	                  its context — no more ferrying. This is the Cursor moment.
118	                  Watch what it still couldn&apos;t see:
119	                </p>
120	                <Era2Companion />
121	              </EraPanel>
122	            )}
123	            {step === "agentic-engineering" && (
124	              <EraPanel
125	                deepCut={
126	                  <p>
127	                    I didn&apos;t build the harness myself. The agent built its
128	                    own auditor; I set the rules it audits against. A page that
129	                    used to take hours of manual diffing came in at 2–3 hours of
130	                    the agent working a list I never had to touch — about a week
131	                    of work I didn&apos;t do.
132	                  </p>
133	                }
134	                expandLabel="Did you know? I didn't build the harness either."
135	                name="Agentic engineering"
136	                reality="Strip the debate away: an agent is an LLM with tools, trapped in a loop. Claude Code put that loop in a terminal — barely useful at first, even on the strongest coding models. Then the loop learned to run longer; minutes became hours. You stop writing syntax and start writing the rules the loop must satisfy."
137	                years="2024 → now"
138	              >
139	                <Era3Loop />
140	                <p className="mb-4 max-w-2xl text-muted-foreground text-sm">
141	                  Here it is with real stakes: a client&apos;s WordPress site,
142	                  rebuilt in Next.js, pixel for pixel. I wrote the rules. The
143	                  agent runs until they&apos;re met:
144	                </p>
145	                <Era3Harness />
