          <motion.div
            animate={{ opacity: 1 }}
            className="flex gap-0.5 rounded-md bg-foreground/5 p-0.5"
            exit={{ opacity: 0 }}
            initial={{ opacity: 0 }}
            key="switch"
            transition={MORPH}
          >
